'use strict';
// Authored solo story. Never used by recorded rivals or authoritative Convoy.
const Intro=(()=>{
const KEY='runroad-opening-v1',names=['One More Seat','The Road Home','Keep the Lights On'];
let saved={done:[],best:{},clean:[]};try{const v=JSON.parse(localStorage.getItem(KEY));if(v){saved.done=Array.isArray(v.done)?v.done.filter(i=>Number.isInteger(i)&&i>=0&&i<3):[];saved.clean=Array.isArray(v.clean)?v.clean.filter(i=>Number.isInteger(i)&&i>=0&&i<3):[];for(let i=0;i<3;i++)if(Number.isFinite(v.best?.[i])&&v.best[i]>0)saved.best[i]=v.best[i]}}catch{}
let active=false,index=0,stage=0,hold=0,clock=0,hudClock=0,line='',lineUntil=0,route='',settled=false,steered=false;
const jun={x:0,y:-60},home={x:0,y:480};let gates=[];
// No personal identifiers or tracking SDK. Enable explicitly in a development console.
let debug=false;const events=[];function event(name,value){if(!debug)return;events.push({name,mission:index,value});if(events.length>100)events.shift()}
function say(text){line=text;lineUntil=clock+6;sound(620,.08)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(saved))}catch{}}
function launch(i=0){if(i<0||i>2)return;C.open('home');active=true;index=i;start();event('started')}
function leave(){active=false}
function prepare(){if(!active)return;stage=hold=clock=hudClock=0;line='';route='';settled=false;steered=false;gates=index===1?[{x:-240,y:-250},{x:240,y:-250},{x:0,y:-480},home]:index===2?[{x:-300,y:-240},{x:300,y:-240},home]:[jun,home];obstacles.length=0;for(const [x,y,r] of [[-480,-420,42],[480,-420,42],[-480,90,40],[480,90,40],[-160,120,34],[160,120,34],[-520,430,40],[520,430,40],[-420,-80,34],[420,-80,34],[-130,-390,32]])obstacles.push({x,y,r,seed:obstacles.length});if(index===1){obstacles.push({x:160,y:-360,r:28,seed:11},{x:320,y:-360,r:28,seed:12})}say(index===0?'Mara: Jun is ahead. Drag to steer toward the amber signal.':index===1?'Jun: Left is safer. Right is shorter. Choose your road.':'Jun: Two supply caches. One garage waiting for us.')}
function target(){return index===1&&stage===0?null:gates[stage]}
function near(p,r=75){return Math.hypot(player.x-p.x,player.y-p.y)<r}
function speed(){return active&&index===0&&stage===0&&near(jun,100)?.18:1}
function pursuit(){return !active||clock>(index===0?(stage===0?999:8):8)}
function tick(dt){if(!active)return;clock+=dt;hudClock-=dt;if((typeof pointer!=='undefined'&&pointer)||(typeof keys!=='undefined'&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].some(k=>keys[k])))steered=true;
 if(index===1&&stage===0){for(let i=0;i<2;i++)if(near(gates[i],85)){route=i?'shortcut':'scenic';if(!i)gates.splice(2,0,{x:-460,y:-450});stage=2;event('route',route);say(i?'Jun: Tight turn ahead. Nitro on the straight!':'Jun: Good choice. Follow the blue signal.');break}}
 else if(index===0&&stage===0){if(near(jun)&&steered){hold+=dt;if(hold>=1.6){stage=1;event('rescued');say('Jun: You came back.  Mara: Get in. We’re going home.')}}else{if(hold>0)event('pickup_interrupted');hold=0}}
 else if(target()&&near(target(),index===0?95:85)){stage++;hold=0;event('checkpoint',stage);if(stage>=gates.length){end(true);return}say(index===1?'Mara: Last stretch. Bring Jun home.': 'SUPPLIES SECURED · Follow the next signal.')}
 if(clock>150){end(false);return}
 if(hudClock<=0){hudClock=P.config.hud;const p=target();const bearing=p?Math.atan2(p.y-player.y,p.x-player.x)*180/Math.PI+90:0;const hint=index===0?(stage===0?(near(jun)&&!steered?'Drag or press an arrow key to pick up Jun':'Approach Jun · slow automatically inside the rescue zone'):'JUN ON BOARD · Reach the green garage'):index===1?(stage===0?'Choose LEFT scenic road or RIGHT shortcut':stage===2?'Reach the north passage · tap Nitro on clear ground':'Reach the green garage'):stage<2?`Recover supply cache ${stage+1}/2`:'Deliver both caches to the garage';$('missionHud').innerHTML=`<div><b>${names[index].toUpperCase()} · STORY ${index+1}/3</b><span>${hint}</span><small>${clock<lineUntil?line:'Steer: drag / arrows · Nitro: tap / Shift · Tutorial protection: reduced damage'}</small></div>${p?`<div class="navigation-hint"><b style="transform:rotate(${bearing}deg)">↑</b><small>${Math.round(Math.hypot(p.x-player.x,p.y-player.y))}m</small></div>`:''}<strong>${index===0&&stage===0?Math.round(Math.min(1,hold/1.6)*100)+'%':Math.ceil(clock)+'s'}</strong>`}}
function draw(g){if(!active)return;const ring=(p,color,label,r=75)=>{g.strokeStyle=color;g.lineWidth=4;g.beginPath();g.arc(p.x,p.y,r,0,Math.PI*2);g.stroke();g.fillStyle=color;g.font='bold 13px sans-serif';g.textAlign='center';g.fillText(label,p.x,p.y-r-12)};
 if(index===1&&stage===0){ring(gates[0],'#8ce4cf','SCENIC · WIDE TURN',85);ring(gates[1],'#ffd47b','SHORTCUT · TIGHT TURN',85);g.fillStyle='#ce825e';g.fillRect(160,-430,35,90);g.fillRect(295,-430,35,90)}else if(target())ring(target(),stage===gates.length-1?'#8ce4cf':'#ffd47b',index===0&&stage===0?'JUN · RESCUE ZONE':stage===gates.length-1?'HOME':'FOLLOW SIGNAL');
 if(typeof People==='undefined')return;People.home(g,home.x,home.y,0,index,clock,[],target()===home);if(index===0&&stage===0)People.person(g,jun.x,jun.y+14,clock,People.look('Jun'),'waiting')}
function finish(won){if(!active||settled)return;settled=true;const first=!saved.done.includes(index);if(won){if(first){saved.done.push(index);C.awardCredits(150)}saved.best[index]=Math.min(saved.best[index]||Infinity,clock);if(player.hp/C.maxHp>=.75&&!saved.clean.includes(index))saved.clean.push(index);save()}event(won?'completed':'failed');$('overTag').textContent=won?'NOBODY DRIVES HOME ALONE':'RETRY WHEN YOU’RE READY';$('overTitle').textContent=won?(index===0?'JUN IS SAFE':index===1?'HOME, TOGETHER':'THE LIGHTS ARE ON'):'WE CAN TRY AGAIN';$('summary').textContent=won?`${index===0?'Jun is safe. The garage has its first supplies.':index===1?'The first garage light is restored.':'The workbench is repaired. Your next road awaits.'} ${first?'+150 credits. ':''}Best: ${saved.best[index].toFixed(1)}s. ${saved.clean.includes(index)?'Clean rescue earned.':'Replay with 75% hull for a clean rescue.'}`:'Jun: We’re still in this together. Restart this short mission; no entry cost.';$('again').textContent=won&&index<2?'NEXT STORY ↗':'RETRY THIS STORY ↗';$('again').onclick=()=>launch(won&&index<2?index+1:index);const extra=document.createElement('button');extra.className='secondary intro-result';extra.textContent=won?'REPLAY FOR A CLEANER ESCAPE':'BACK TO GARAGE';extra.onclick=()=>won?launch(index):C.open('home');$('over').querySelectorAll('.intro-result').forEach(e=>e.remove());$('over').append(extra)}
function homeView(){return `<section class="opening-card"><div class="eyebrow">NOBODY DRIVES HOME ALONE</div><h3>BRING SOMEONE HOME.</h3><p>Three short solo stories. Rescue Jun, choose your escape and restore the garage. Tutorial protection reduces damage; these runs are unranked.</p><div class="opening-lights" aria-label="${saved.done.length} of 3 garage milestones">${['SUPPLIES','FIRST LIGHT','WORKBENCH'].map((s,i)=>`<span>${saved.done.includes(i)?'✦':'◇'} ${s}</span>`).join('')}</div>${names.map((n,i)=>`<button class="secondary" data-story="${i}">${saved.done.includes(i)?'REPLAY': 'PLAY'} ${i+1} · ${n}</button>`).join('')}<button class="secondary" data-story-skip>SKIP TO CAMPAIGN ↗</button><p>Want a real friend rescue? Open Play with friends → Live Convoy. Requires two connected players.</p></section>`}
return{launch,leave,prepare,tick,draw,finish,speed,pursuit,homeView,get active(){return active},get done(){return saved.done.length},get title(){return names[index]},get maxCops(){return index===0?2:3},get armor(){return .45},get testState(){return{stage,hold,clock,route,target:target(),saved}},debugEvents(enable){debug=!!enable;return events.slice()}};
})();
